      title: "51. Viața cotidiană în Evul Mediu",
        summary: `
            <h3>1. Cum trăiau țăranii în Evul Mediu?</h3>
            <p>Majoritatea oamenilor trăiau la sate. Familia era mare (părinți, copii, bunici), iar copiii munceau de mici. Nu existau școli, iar țăranii nu știau să scrie sau să citească.</p>
            <p>Hainele se făceau în casă din lână sau cânepă, iar mâncarea consta mai ales din legume, lactate și pește (carnea se mânca rar). Cel mai important condiment era <strong>sarea</strong>, pentru că piperul era extrem de scump.</p>

            <h3>2. Biserica satului și condițiile de trai</h3>
            <p><strong>Biserica</strong> era centrul vieții sociale: aici oamenii se strângeau la slujbe, nunți și botezuri. Pentru schimbul de produse, oamenii se întâlneau la <strong>târguri</strong>.</p>
            <p>Viața era grea, iar din cauza bolilor și a igienei slabe, speranța de viață era de doar <strong>~30 de ani</strong> (la 45 de ani un om era privit ca un bătrân).</p>

            <h3>3. Agricultura și categoriile de țărani</h3>
            <p>Pământul era cea mai importantă bogăție. Existau două mari categorii de țărani:</p>
            <ul>
                <li><strong>Țăranii liberi:</strong> aveau pământul lor și plăteau taxe doar regelui și Bisericii.</li>
                <li><strong>Țăranii dependenți:</strong> trăiau pe pământul nobililor (seniorilor), cărora le dădeau o parte din recoltă și le prestau munci în schimbul protecției.</li>
            </ul>
            <p>Din secolele XI-XII au apărut inventii care au ușurat munca: <strong>plugul de fier</strong>, <strong>moara de apă</strong> și <strong>moara de vânt</strong>. De asemenea, prelucrarea metalelor a devenit mai bună decât în Antichitate.</p>
        `,
