           title: "1. Călătoriile și percepția spațiului în Evul Mediu",
        summary: `
            <h3>1. Percepția spațiului și motivele călătoriilor</h3>
            <p>Oamenii din Evul Mediu aveau informații puține și adesea eronate despre lumea extraeuropeană, sprijinindu-se pe hărți antice sau arabe. Principalele cauze care îi îndemnau pe oameni să călătorească erau:</p>
            <ul>
                <li><strong>Comerțul:</strong> negustorii înfruntau riscuri majore pe uscat și pe apă pentru a obține profituri mari.</li>
                <li><strong>Mântuirea și vindecarea:</strong> pelerinii călătoreau spre locuri sfinte precum Ierusalim, Roma sau mănăstiri renumite.</li>
                <li><strong>Interesele politice și religioase:</strong> solii papali sau monarhii trimiteau emisari în misiune diplomatică și de convertire.</li>
            </ul>

            <h3>2. Mijloacele de transport</h3>
            <p>Pe uscat se foloseau căruțele (greu de utilizat când drumurile deveneau impracticabile din cauza ploilor), caii sau mersul pe jos. Pe apă, navigația se concentra în special în zone cunoscute și sigure; cea mai circulată era <strong>Marea Mediterană</strong>, unde galerele venețiene și genoveze asigurau legătura economică cu Orientul prin intermediul <em>Drumului Mătăsii</em>.</p>

            <h3>3. Călători celebri</h3>
            <ul>
                <li><strong>Giovanni da Pian del Carpine:</strong> călugăr franciscan trimis ca sol al Papei la curtea mongolilor (1245–1247).</li>
                <li><strong>Marco Polo:</strong> negustor venețian care a călătorit în China (1271–1295), consemnându-și experiențele în celebra lucrare <em>Cartea minunilor lumii</em>.</li>
            </ul>
        `,
