        title: "12. Un model democratic - SUA",
        summary: `
            <h3>1. Democrația și Constituția americană</h3>
            <p>Statele Unite ale Americii reprezintă primul stat modern organizat pe principii democratice, având prima Constituție scrisă (1787) și prima funcție de președinte de republică.</p>
            <ul>
                <li><strong>Separația puterilor:</strong> Președintele este șeful statului și al Guvernului (puterea executivă), iar Congresul (format din Camera Reprezentanților și Senat) exercită puterea legislativă.</li>
                <li><strong>Dreptul de vot:</strong> a fost extins treptat — bărbații afro-americani și nativi l-au primit în 1870, iar femeile în 1920.</li>
            </ul>

            <h3>2. Politica externă: izolaționism vs. implicare</h3>
            <p>După Primul Război Mondial, Senatul american a refuzat intrarea în Liga Națiunilor, promovând o politică de neintervenție în afacerile europene, numită <strong>izolaționism</strong>.</p>
            <p>Ascensiunea nazismului în Germania l-a determinat pe președintele <strong>F.D. Roosevelt</strong> să pregătească țara pentru apărarea democrației, crescând bugetul armatei din 1938.</p>

            <h3>3. Prosperitatea și sistemul politic</h3>
            <p>Prosperitatea SUA s-a bazat pe un <strong>sistem bipartit</strong> (Partidul Democrat și Partidul Republican), care au alternat la guvernare. În mod tradițional, statul nu intervenea în economie, însă pentru depășirea Marii Crize a fost necesară intervenția fermă prin programul <em>New Deal</em>.</p>
        `,
